import{_ as t,o as a,c as r,a2 as d}from"./chunks/framework.BvlN9b-o.js";const f=JSON.parse('{"title":"Rust Public Integration Map","description":"","frontmatter":{"docLocale":"en","counterpart":"/reference/rust","contentType":"reference","prev":false,"next":false},"headers":[],"relativePath":"en/reference/rust.md","filePath":"en/reference/rust.md"}'),o={name:"en/reference/rust.md"};function s(c,e,n,i,l,b){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="rust-public-integration-map" tabindex="-1">Rust Public Integration Map <a class="header-anchor" href="#rust-public-integration-map" aria-label="Permalink to &quot;Rust Public Integration Map&quot;">​</a></h1><p>This page is for backend developers implementing their own business modules. Look up HTTP DTOs in the <a href="./api">API reference</a>; linked source defines the complete Rust signatures and limits. Complete <a href="./../guides/new-module">Add a backend module</a>, then select the capabilities you need.</p><p><code>saas_app</code> exposes SaaS Core and HTTP boundaries. <code>saas_platform</code> exposes configuration and infrastructure adapters. Business modules call these public interfaces; API and Worker compose them explicitly at the application layer. The current organization model is a single Organization. Storing multiple customers in one database does not automatically provide tenant isolation.</p><h2 id="http-and-identity" tabindex="-1">HTTP and Identity <a class="header-anchor" href="#http-and-identity" aria-label="Permalink to &quot;HTTP and Identity&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Public entry</th><th>Calling context</th><th>Return or error</th><th>Responsibility and limits</th><th>Checked usage</th></tr></thead><tbody><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/lib.rs" target="_blank" rel="noreferrer"><code>compose_routes_with_options</code></a> / <code>CoreOptions</code></td><td>Application startup: pool, authentication settings, business Router and merged OpenAPI</td><td>Axum <code>Router</code></td><td>Supplies Core routes, request_id, rate limits and common fallbacks; finish business state before merge</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/examples/tutorial-tickets/preview.rs" target="_blank" rel="noreferrer">First module</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/health.rs" target="_blank" rel="noreferrer">HTTP health tests</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>BoundedJson</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>ApiQuery</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>ApiPath</code></a></td><td>Handler wrapped by Core request_context; JSON extractor comes last</td><td>Deserialized DTO; rejection is a public <code>Response</code></td><td>Reads the protocol; Domain still validates length and business rules</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/registration.rs" target="_blank" rel="noreferrer">Identity HTTP tests</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>require_session</code></a></td><td>Pool, <code>AuthSettings</code>, headers, <code>RequestId</code>, mutation flag</td><td><code>Result&lt;CurrentSession, Response&gt;</code></td><td>Mutations check Origin/CSRF; explicit Authorization does not fall back to Cookie; write transactions must lock active membership again</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/sessions.rs" target="_blank" rel="noreferrer">Session HTTP tests</a>, <a href="./../tutorials/sessions">Session integration</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/api_keys/authentication.rs" target="_blank" rel="noreferrer"><code>require_read</code></a></td><td>Read endpoint with the business scope registered during composition</td><td><code>Result&lt;ReadActor, Response&gt;</code></td><td>Bearer takes precedence; after credential, membership and scope checks, business code checks resource access</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/api_keys.rs" target="_blank" rel="noreferrer">API Key HTTP tests</a>, API Key integration</td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/api_keys/mod.rs" target="_blank" rel="noreferrer"><code>KeyScope</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/api_keys/mod.rs" target="_blank" rel="noreferrer"><code>core_scopes</code></a></td><td>API application composition</td><td>Scope declaration / Core scope list</td><td>Add business read scopes to CoreOptions; a scope does not grant resource access</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/apps/api/src/lib.rs" target="_blank" rel="noreferrer">API assembly</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>background_credential</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>credential_is_current</code></a></td><td>Authorized actor&#39;s request transaction / Worker publication transaction</td><td><code>Option&lt;CredentialRef&gt;</code> / <code>bool</code>, database errors</td><td>Persist credential references instead of Cookies; Worker checks never extend original credential lifetime</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/sessions.rs" target="_blank" rel="noreferrer">Credential behavior tests</a></td></tr></tbody></table><p><code>require_session</code> returns identity. Your ticket or billing rules remain responsible for current resource access. Check those rules in the same use case as the mutation to avoid a check followed by a write in a separate transaction.</p><h2 id="caller-owned-database-transactions" tabindex="-1">Caller-Owned Database Transactions <a class="header-anchor" href="#caller-owned-database-transactions" aria-label="Permalink to &quot;Caller-Owned Database Transactions&quot;">​</a></h2><p>These entries accept <code>&amp;mut PgConnection</code>. Pass the same <code>&amp;mut *tx</code>, check every result and commit once from the business use case. Business data, audit and jobs belong in that shared transaction.</p><table tabindex="0"><thead><tr><th>Public entry</th><th>Input / output</th><th>Errors</th><th>Transaction responsibility</th><th>Checked usage</th></tr></thead><tbody><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/organization/mod.rs" target="_blank" rel="noreferrer"><code>enroll</code></a></td><td>New user id → <code>MemberRole</code></td><td><code>sqlx::Error</code></td><td>Enroll in the current organization within account creation; the organization row serializes first-Owner initialization</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/registration.rs" target="_blank" rel="noreferrer">Registration transaction tests</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/organization/mod.rs" target="_blank" rel="noreferrer"><code>active_role_in</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/organization/mod.rs" target="_blank" rel="noreferrer"><code>lock_memberships</code></a></td><td>User id / id list → current role / membership records</td><td><code>sqlx::Error</code>; membership may be missing or inactive</td><td>Lock members before resources; lock multiple members in id order, matching administration</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/membership_policy.rs" target="_blank" rel="noreferrer">Membership concurrency tests</a>, <a href="./../tutorials/members">Member guide</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/audit/mod.rs" target="_blank" rel="noreferrer"><code>append</code></a> / <code>Event</code></td><td>Actor, action, resource and <code>Source</code> → <code>()</code></td><td><code>sqlx::Error</code></td><td>Share the business transaction; audit failure rolls business data back; metadata excludes arbitrary request JSON and secrets</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/audit.rs" target="_blank" rel="noreferrer">Audit HTTP tests</a>, Audit integration</td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/idempotency/mod.rs" target="_blank" rel="noreferrer"><code>fingerprint</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/idempotency/mod.rs" target="_blank" rel="noreferrer"><code>claim</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/idempotency/mod.rs" target="_blank" rel="noreferrer"><code>complete</code></a></td><td><code>Attempt</code>: actor, scope, key and payload hash → previous response / <code>()</code></td><td><code>InvalidKey</code>, <code>Conflict</code>, <code>Unavailable</code></td><td>Authorize before claim; replay existing responses; complete new results before commit; failures leave no business data or reservation</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/examples/tutorial-tickets/application.rs" target="_blank" rel="noreferrer">Ticket idempotency</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/jobs/mod.rs" target="_blank" rel="noreferrer"><code>enqueue</code></a> / <code>NewJob</code></td><td>Kind, schema_version, business payload, attempt budget and correlation → Job id</td><td><code>sqlx::Error</code></td><td>Enqueue with the business snapshot; kind needs a registered Worker Handler; payload excludes tokens and signed URLs</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/jobs.rs" target="_blank" rel="noreferrer">Public job tests</a>, Job guide</td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/notifications/mod.rs" target="_blank" rel="noreferrer"><code>on_job_outcome</code></a> / <code>JobNotification</code></td><td>Job id, recipient, stable event_key, generic subject and target → <code>()</code></td><td><code>sqlx::Error</code></td><td>Register intent with enqueue; Jobs publishes inside its terminal transaction; targets check current access</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/notifications.rs" target="_blank" rel="noreferrer">Notification HTTP tests</a>, Notification guide</td></tr></tbody></table><h2 id="files-and-worker" tabindex="-1">Files and Worker <a class="header-anchor" href="#files-and-worker" aria-label="Permalink to &quot;Files and Worker&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Public entry</th><th>Input / output</th><th>Errors or limits</th><th>Calling responsibility</th><th>Checked usage</th></tr></thead><tbody><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer"><code>FileService</code></a>: <code>start</code>, <code>upload_capability</code>, <code>plan_completion</code>, <code>verify_candidate</code>, <code>publish</code>, <code>download</code></td><td>Upload registration → capability → completion plan → verified candidate → ready file / download capability</td><td><code>files::Error</code>; objects may be missing, changed, expired or rejected</td><td>Business code owns attachment access; object I/O runs outside short transactions; publication and business records share one transaction</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/platform/tests/object_storage.rs" target="_blank" rel="noreferrer">Object storage integration tests</a>, Files integration</td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/files/cleanup.rs" target="_blank" rel="noreferrer"><code>mark_deleting</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/files/cleanup.rs" target="_blank" rel="noreferrer"><code>cleanup_handler</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/files/cleanup.rs" target="_blank" rel="noreferrer"><code>cleanup_maintenance</code></a></td><td>File id in caller&#39;s transaction / Worker and maintenance registration</td><td>Database or job errors</td><td>Remove business visibility transactionally, then clean objects asynchronously; API and Worker share storage settings</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/examples/tutorial-tickets/mod.rs" target="_blank" rel="noreferrer">Course source</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/jobs/worker.rs" target="_blank" rel="noreferrer"><code>Handler</code></a> / <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/jobs/worker.rs" target="_blank" rel="noreferrer"><code>Worker</code></a></td><td><code>kind()</code> + <code>run(&amp;Lease)</code>; pool, Handler list, <code>WorkerPolicy</code></td><td><code>Permanent</code>, <code>Transient</code>, <code>LostLease</code>; Worker database errors</td><td>Register at the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/apps/worker/src/main.rs" target="_blank" rel="noreferrer">Worker assembly</a>; use <code>run_once</code> in controlled tests and <code>run_until</code> for bounded shutdown</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/jobs.rs" target="_blank" rel="noreferrer">Job integration tests</a>, Recovery guide</td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/jobs/mod.rs" target="_blank" rel="noreferrer"><code>Lease</code></a>: <code>lock_current</code>, <code>succeed</code>, <code>heartbeat</code></td><td>Current lease + connection / pool → <code>()</code></td><td><code>JobError</code></td><td>Call lock_current before changing results; commit business results and succeed together; a lost lease cannot publish</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/jobs.rs" target="_blank" rel="noreferrer">Job integration tests</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/mail/mod.rs" target="_blank" rel="noreferrer"><code>MailService</code></a>: <code>seal</code>, <code>open</code>, <code>send_plain_text</code></td><td>Context binding, protected materials / SMTP text</td><td><code>MaterialError</code>, transport errors; from_env returns None when unconfigured</td><td>Encrypt persisted mail secrets and bind their context; caller defines retries and one-time consumption; logs exclude message bodies</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/mail_materials.rs" target="_blank" rel="noreferrer">Mail material tests</a>, <a href="./../tutorials/password-reset">Password recovery</a></td></tr></tbody></table><h2 id="platform-and-verification" tabindex="-1">Platform and Verification <a class="header-anchor" href="#platform-and-verification" aria-label="Permalink to &quot;Platform and Verification&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Public entry</th><th>Return / boundary</th><th>Usage guide</th></tr></thead><tbody><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/platform/src/config.rs" target="_blank" rel="noreferrer"><code>Settings</code></a> / <code>from_env</code></td><td><code>Result&lt;Settings, ConfigError&gt;</code>; invalid startup settings stop the process</td><td><a href="./config">Generated server configuration</a>, <a href="./configuration-sources">Variable sources</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/platform/src/cache.rs" target="_blank" rel="noreferrer"><code>Cache</code></a>: <code>get</code>, <code>put</code>, <code>remove</code></td><td><code>Lookup</code>, <code>CacheUnavailable</code>; shared deadline; Redis availability is not guaranteed</td><td>Cache integration, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/cache.rs" target="_blank" rel="noreferrer">Real cache tests</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/rate_limit/mod.rs" target="_blank" rel="noreferrer"><code>RateLimiter</code></a></td><td>HTTP request budgets; share the instance in API composition</td><td><a href="./../tutorials/rate-limits">Rate limits</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/rate_limits.rs" target="_blank" rel="noreferrer">Rate-limit HTTP tests</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/platform/src/telemetry/mod.rs" target="_blank" rel="noreferrer"><code>init</code></a> / <code>TelemetryGuard</code></td><td>Initialize telemetry; shut the guard down during bounded shutdown</td><td>Logs and tracing, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/telemetry_shutdown.rs" target="_blank" rel="noreferrer">Shutdown tests</a></td></tr></tbody></table><p>A source signature does not prove commit behavior. Write your own <a href="./../testing/feedback-loop">HTTP behavior tests</a> for rejection, replay, rollback and stale leases. The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/examples/tutorial-tickets/application.rs" target="_blank" rel="noreferrer">Ticket use cases</a> and <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/tutorial_course.rs" target="_blank" rel="noreferrer">Course HTTP tests</a> show integration for your own business. See <a href="./../architecture/boundaries">Module relationships</a> for ownership and removal boundaries.</p><p>Complete reference-business guides: <a href="./../tutorials/edit-conflicts">Idempotency and versions</a>, <a href="./../tutorials/attachments">Files</a>, <a href="./../tutorials/document-exports">Jobs</a>, <a href="./../tutorials/job-recovery">Recovery</a>, <a href="./../tutorials/deletion-cleanup">Deletion</a>, <a href="./../tutorials/export-notifications">Notifications</a>, <a href="./../tutorials/audit-history">Audit</a>, <a href="./../tutorials/api-keys">API Keys</a>, <a href="./../tutorials/versioned-cache">Cache</a> and <a href="./../tutorials/observability">Tracing</a>. This reference-business reading section is removed with knowledge; shared capability guides remain.</p><hr><p>Source version：<code>e87f840d6dfc</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/reference/rust.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>',17)])])}const p=t(o,[["render",s]]);export{f as __pageData,p as default};
